import React, { useState } from 'react'

import ApplicationStepper
    from './components/ApplicationStepper'

import LoanTypeSelection
    from './components/LoanTypeSelection'


function CreateApplication() {

    const [currentStep, setCurrentStep] = useState(1)

    const [application, setApplication] = useState({
        loanType: null,
        agentId: null,
    })


    const nextStep = () => {

        setCurrentStep((previousStep) =>
            Math.min(previousStep + 1, 5)
        )

    }


    const previousStep = () => {

        setCurrentStep((previousStep) =>
            Math.max(previousStep - 1, 1)
        )

    }


    const handleLoanTypeChange = (loanType) => {

        setApplication((previous) => ({
            ...previous,
            loanType,
        }))

    }


    return (

        <div className="p-4 md:p-6 space-y-5">


            {/* PAGE HEADER */}

            <div className="flex items-center justify-between">

                <div>

                    <h1 className="text-3xl md:text-4xl font-normal text-base-content">
                        Create Application
                    </h1>

                    <p className="mt-2 text-base text-base-content/60">
                        Create and submit a new loan application
                    </p>

                </div>


                <button
                    type="button"
                    className="btn btn-outline hidden sm:flex"
                >
                    Save Draft
                </button>

            </div>


            {/* STEPPER */}

            <ApplicationStepper
                currentStep={currentStep}
            />


            {/* CONTENT */}

            <div className="bg-base-100 border border-base-300 rounded-2xl shadow-sm">

                <div className="p-5 md:p-6">


                    {/* STEP 1 */}

                    {currentStep === 1 && (

                        <LoanTypeSelection
                            selectedLoanType={application.loanType}
                            onLoanTypeChange={handleLoanTypeChange}
                        />

                    )}


                    {/* STEP 2 */}

                    {currentStep === 2 && (

                        <div>

                            <h2 className="text-xl font-semibold">
                                Applicant Information
                            </h2>

                            <p className="mt-1 text-sm text-base-content/60">
                                Enter the applicant's basic information.
                            </p>

                        </div>

                    )}


                    {/* STEP 3 */}

                    {currentStep === 3 && (

                        <div>

                            <h2 className="text-xl font-semibold">
                                Loan Details
                            </h2>

                            <p className="mt-1 text-sm text-base-content/60">
                                Enter the loan-specific information.
                            </p>

                        </div>

                    )}


                    {/* STEP 4 */}

                    {currentStep === 4 && (

                        <div>

                            <h2 className="text-xl font-semibold">
                                Documents
                            </h2>

                            <p className="mt-1 text-sm text-base-content/60">
                                Upload the required documents.
                            </p>

                        </div>

                    )}


                    {/* STEP 5 */}

                    {currentStep === 5 && (

                        <div>

                            <h2 className="text-xl font-semibold">
                                Review & Submit
                            </h2>

                            <p className="mt-1 text-sm text-base-content/60">
                                Review the application before submitting it.
                            </p>

                        </div>

                    )}

                </div>

            </div>


            {/* NAVIGATION */}

            <div className="flex items-center justify-between">


                <button
                    type="button"
                    className="btn btn-outline"
                    disabled={currentStep === 1}
                    onClick={previousStep}
                >
                    ← Back
                </button>


                {currentStep < 5 ? (

                    <button
                        type="button"
                        className="btn text-white border-0 shadow-sm"
                        style={{
                            backgroundColor: 'rgb(143, 212, 0)',
                        }}
                        onClick={nextStep}
                    >
                        Continue →
                    </button>

                ) : (

                    <button
                        type="button"
                        className="btn text-white border-0 shadow-sm"
                        style={{
                            backgroundColor: 'rgb(143, 212, 0)',
                        }}
                    >
                        Submit Application
                    </button>

                )}

            </div>

        </div>
    )
}

export default CreateApplication
